WITH prices AS (SELECT 'A100 SXM4' AS gpu, substr(json_extract(value,'$.timestamp'),1,10) AS date, json_extract(value,'$.index_value') AS price FROM json_each(readfile('evidence/ornn-A100%20SXM4.json'),'$.data') UNION ALL SELECT 'B200' AS gpu, substr(json_extract(value,'$.timestamp'),1,10) AS date, json_extract(value,'$.index_value') AS price FROM json_each(readfile('evidence/ornn-B200.json'),'$.data') UNION ALL SELECT 'H100 SXM' AS gpu, substr(json_extract(value,'$.timestamp'),1,10) AS date, json_extract(value,'$.index_value') AS price FROM json_each(readfile('evidence/ornn-H100%20SXM.json'),'$.data') UNION ALL SELECT 'H200' AS gpu, substr(json_extract(value,'$.timestamp'),1,10) AS date, json_extract(value,'$.index_value') AS price FROM json_each(readfile('evidence/ornn-H200.json'),'$.data') UNION ALL SELECT 'RTX 5090' AS gpu, substr(json_extract(value,'$.timestamp'),1,10) AS date, json_extract(value,'$.index_value') AS price FROM json_each(readfile('evidence/ornn-RTX%205090.json'),'$.data')), notes AS (SELECT CAST(key AS INTEGER) AS ord, json_extract(value,'$[0]') AS gpu, json_extract(value,'$[2]')/100.0 AS reportedChange FROM json_each(readfile('evidence/user-inputs.json'),'$.firstNote.rows')) SELECT n.ord AS 'order', n.gpu, a.price AS before, b.price AS after, n.reportedChange, b.price/a.price-1.0 AS calculatedChange, CASE WHEN round((b.price/a.price-1.0)*100.0,1)=round(n.reportedChange*100.0,1) THEN '吻合（按原文精度）' ELSE '不一致' END AS status FROM notes n JOIN prices a ON a.gpu=n.gpu AND a.date='2026-08-29' JOIN prices b ON b.gpu=n.gpu AND b.date='2026-09-05' ORDER BY n.ord;
